import java.util.Arrays;

/**
 * <a href="https://www.codewars.com/kata/5526fc09a1bbd946250002dc/train/java">Find the Parity Outlier</a>
 *
 * <p>You are given an array (which will have a length of at least 3, but could be very large) containing integers.
 * The array is either entirely comprised of odd integers or entirely comprised of even integers except for a single
 * integer N. Write a method that takes the array as an argument and returns this "outlier" N.
 *
 * <p>Examples
 * [2, 4, 0, 100, 4, 11, 2602, 36]
 * Should return: 11 (the only odd number)
 *
 * [160, 3, 1719, 19, 11, 13, -21]
 * Should return: 160 (the only even number)
 *
 * <p>Note:
 * Your solution should be able to handle both the odd and even number versions of the list, and is able to handle
 * lists of any length, including the empty list.
 */
public class FindTheParityOutlier {

  public static int find(int[] integers) {
    int[] even = Arrays.stream(integers).filter(i -> i % 2 == 0).toArray();
    int[] odd = Arrays.stream(integers).filter(i -> i % 2!= 0).toArray();
    return even.length == 1? even[0] : odd[0];
  }
}
