public class Find_the_middle_element {

    public static int[] middlePermutation(int[] arr) {
        int[] result = new int[arr.length];
        int index = 0;
        for (int i = 0; i < arr.length; i++) {
            for (int j = 0; j < arr.length; j++) {
                if (i!= j) {
                    result[index] = arr[i] * arr[j];
                    index++;
                }
            }
        }
        Arrays.sort(result);
        return result;
    }

