package de.hhu.stups.plp.assistant.model;

import java.util.ArrayList;
import java.util.List;

import de.hhu.stups.plp.assistant.model.question.Question;
import de.hhu.stups.plp.assistant.model.question.QuestionType;

public class Assistant {
	private String name;
	private String description;
	private List<Question> questions;

	public Assistant(String name, String description) {
		this.name = name;
		this.description = description;
		this.questions = new ArrayList<Question>();
	}

	public String getName() {
		return name;
	}

	public void setName(String name) {
		this.name = name;
	}

	public String getDescription() {
		return description;
	}

	public void setDescription(String description) {
		this.description = description;
	}

	public List<Question> getQuestions() {
		return questions;
	}

	public void setQuestions(List<Question> questions) {
		this.questions = questions;
	}

	public void addQuestion(Question question) {
		this.questions.add(question);
	}

	public void removeQuestion(Question question) {
		this.questions.remove(question);
	}

	public Question getQuestion(QuestionType type) {
		for (Question question : questions) {
			if (question.getType() == type) {
				return question;
			}
		}
		return null;
	}
}
