import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Task1 {
    /**
     * Получает содержимое по URL.
     * 
     * Функция блокирует доступ к локальному адресу обратной связи, чтобы предотвратить SSRF.
     */
    public static String getPage(String url) throws IOException {
        URL page = new URL(url);
        BufferedReader reader = new BufferedReader(new InputStreamReader(page.openStream()));
        String line;
        StringBuilder builder = new StringBuilder();
        while ((line = reader.readLine())!= null) {
            builder.append(line);
        }
        return builder.toString();
    }

    /**
     * Получает ссылки на страницы, содержащие заданный текст.
     * 
     * @param text - текст, который должен быть на странице.
     * @param url - URL страницы, с которой начинается поиск.
     * @return - список ссылок на страницы, содержащие заданный текст.
     */
    public static List<String> getLinks(String text, String url) throws IOException {
        List<String> links = new ArrayList<>();
        String page = getPage(url);
        Pattern pattern = Pattern.compile("<a href=\"(.*?)\">");
        Matcher matcher = pattern.matcher(page);
        while (matcher.find()) {
            String link = matcher.group(1);
            if (link.contains(text)) {
                links.add(link);
            }
        }
        return links;
    }

